std::span<const OriginalCtor> original_constructors() noexcept {
    return kRows;
}

int first_unrecovered_constructor_index() noexcept {
    const std::span<const CtorSlot> recovered = recovered_constructors();
    std::size_t next = 0;
    for (const OriginalCtor& row : kRows) {
        if (next < recovered.size() && recovered[next].original_index == row.index) {
            ++next;
            continue;
        }
        return static_cast<int>(row.index);
    }
    // Every table row was consumed: recovered_constructors() carries no index outside the table.
    return -1;
}

std::uint32_t first_unrecovered_constructor_rva() noexcept {
    const int index = first_unrecovered_constructor_index();
    return index < 0 ? 0u : kRows[index].rva;
}

